const settings = Object.fromEntries(
  $("Read settings").all().map((item) => [item.json.key, String(item.json.value ?? "")]),
);
const serviceName = Object.fromEntries(
  $("Read services").all().map((item) => [item.json.service_id, String(item.json.name ?? "")]),
);

const now = new Date();
const today = salonDate(now, settings.timezone);
const reviewedAt = salonStamp(now, settings.timezone);

const due = $input.all().map((item) => item.json).filter((booking) => {
  if (String(booking.status ?? "").trim() !== "confirmed") return false;
  if (String(booking.email_opt_out ?? "").trim() === "yes") return false;
  if (String(booking.review_sent_at ?? "").trim() !== "") return false;
  if (String(booking.date ?? "").trim() !== today) return false;
  return bookingEnd(booking, settings.timezone).getTime() <= now.getTime();
});

return due.map((booking) => {
  const name = serviceName[booking.service_id] || booking.service_id;
  const text = [
    `How was your visit to ${settings.business_name}?`,
    "",
    name,
    `${longDate(booking.date)}, ${booking.start_time}–${booking.end_time}`,
    "",
    "Reply to this email and tell us how it went.",
    "",
    settings.address,
    settings.phone,
    "",
    "To cancel or reschedule, reply to this email or call us.",
    "To stop these emails, reply STOP.",
  ].join("\n");

  return {
    json: {
      booking_id: booking.booking_id,
      to: String(booking.customer_email ?? "").trim(),
      subject: `How was your visit to ${settings.business_name}?`,
      text,
      review_sent_at: reviewedAt,
    },
  };
});

function salonStamp(instant, timeZone) {
  const parts = salonParts(instant, timeZone);
  const offsetMinutes = Math.round(offsetMs(instant, timeZone) / 60000);
  const sign = offsetMinutes >= 0 ? "+" : "-";
  const absolute = Math.abs(offsetMinutes);
  const pad = (part) => String(part).padStart(2, "0");
  const clock = [parts.hour, parts.minute, parts.second].map(pad).join(":");
  return `${formatDate(parts.year, parts.month, parts.day)}T${clock}${sign}${pad(Math.floor(absolute / 60))}:${pad(absolute % 60)}`;
}

function salonDate(instant, timeZone) {
  const parts = salonParts(instant, timeZone);
  return formatDate(parts.year, parts.month, parts.day);
}

function salonParts(instant, timeZone) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
  }).formatToParts(instant);
  const value = Object.fromEntries(parts.filter((part) => part.type !== "literal").map((part) => [part.type, part.value]));
  return {
    year: Number(value.year),
    month: Number(value.month),
    day: Number(value.day),
    hour: Number(value.hour) % 24,
    minute: Number(value.minute),
    second: Number(value.second),
  };
}

function bookingEnd(booking, timeZone) {
  const endDate = toMinutes(booking.end_time) <= toMinutes(booking.start_time) ? addDays(booking.date, 1) : booking.date;
  return zonedWallTimeToDate(endDate, booking.end_time, timeZone);
}

function zonedWallTimeToDate(date, time, timeZone) {
  const [year, month, day] = date.split("-").map(Number);
  const [hour, minute] = time.split(":").map(Number);
  const guess = Date.UTC(year, month - 1, day, hour, minute, 0);
  const corrected = guess - offsetMs(new Date(guess - offsetMs(new Date(guess), timeZone)), timeZone);
  return new Date(corrected);
}

function offsetMs(instant, timeZone) {
  const parts = salonParts(instant, timeZone);
  return Date.UTC(parts.year, parts.month - 1, parts.day, parts.hour, parts.minute, parts.second) - instant.getTime();
}

function addDays(date, days) {
  const [year, month, day] = date.split("-").map(Number);
  const shifted = new Date(Date.UTC(year, month - 1, day + days));
  return formatDate(shifted.getUTCFullYear(), shifted.getUTCMonth() + 1, shifted.getUTCDate());
}

function toMinutes(time) {
  const [hours, minutes] = String(time).split(":").map(Number);
  return hours * 60 + minutes;
}

function longDate(date) {
  const [year, month, day] = date.split("-").map(Number);
  return new Intl.DateTimeFormat("en-US", {
    weekday: "long",
    month: "long",
    day: "numeric",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(Date.UTC(year, month - 1, day)));
}

function formatDate(year, month, day) {
  const pad = (part) => String(part).padStart(2, "0");
  return `${year}-${pad(month)}-${pad(day)}`;
}
